/** Uppercased lookup; falls back to '?' like the TS getGlyph(). */
inline const uint16_t* getGlyph10(char ch) {
  const char key = (ch >= 'a' && ch <= 'z') ? (char)(ch - 'a' + 'A') : ch;
  const uint16_t* fallback = nullptr;
  for (int i = 0; i < kGlyph10Count; i++) {
    if (kGlyphs10[i].ch == key) return kGlyphs10[i].rows;
    if (kGlyphs10[i].ch == '?') fallback = kGlyphs10[i].rows;
  }
  return fallback;
}

